using XzLib
using BufferIO: BufferIO, BufReader, CursorReader, IOError, VecWriter
using BufferIO.Testing: BoundedWriter
using Random
using Test

include("seekable.jl")

# Generated by `lzma.compress(b"foo")` on CPython 3.5.2.
const FOO = Vector(b"\xfd7zXZ\x00\x00\x04\xe6\xd6\xb4F\x02\x00!\x01\x16\x00\x00\x00t/\xe5\xa3\x01\x00\x02foo\x00\x00X\x15\xa9{,\xe6,\x98\x00\x01\x1b\x03\x0b/\xb9\x10\x1f\xb6\xf3}\x01\x00\x00\x00\x00\x04YZ")

# Fails once, on its `failat`th attempt to make room, like a transient disk error.
mutable struct FlakySink <: BufferIO.AbstractBufWriter
    const inner::BoundedWriter
    failat::Int
end
FlakySink(sink::Vector{UInt8}, failat::Int) = FlakySink(BoundedWriter(sink, 4096), failat)
BufferIO.get_buffer(sink::FlakySink) = BufferIO.get_buffer(sink.inner)
BufferIO.consume(sink::FlakySink, n::Int) = BufferIO.consume(sink.inner, n)
BufferIO.grow_buffer(sink::FlakySink) =
    if iszero(sink.failat -= 1) error("transient failure") else BufferIO.grow_buffer(sink.inner) end
Base.flush(sink::FlakySink) = flush(sink.inner)
Base.close(sink::FlakySink) = close(sink.inner)
Base.isopen(sink::FlakySink) = isopen(sink.inner)

nblocks(compressed) =length(XzSeekableReader(IOBuffer(compressed)).index.blocks)

@testset "Round trips" begin
    rng = Xoshiro(1)
    @testset "$(length(data)) bytes, level $level, check $check, threads=$threads" for
            data in (UInt8[], [0x01], rand(rng, UInt8, 100), repeat(SAMPLE, 3)),
            level in (0, 6), check in (:none, :crc32, :crc64, :sha256), threads in (1, 4)
        compressed = compress_xz(data; level, check, threads, blocksize = 100_000)
        @test decompress_xz(compressed) == data
        @test decompress_xz(compressed; threads) == data
    end
    @testset "tiny buffers" begin
        sink = UInt8[]
        XzWriter(BoundedWriter(sink, 7); bufsize = 5) do writer
            for chunk in Iterators.partition(SAMPLE, 1000)
                write(writer, chunk)
            end
        end
        @test XzReader(read, BufReader(IOBuffer(sink), 3); bufsize = 7) == SAMPLE
    end
    @testset "byte by byte" begin
        sink = VecWriter()
        XzWriter(sink; blocksize = 1000) do writer
            foreach(byte -> write(writer, byte), SAMPLE[1:5000])
        end
        @test decompress_xz(sink.vec) == SAMPLE[1:5000]
    end
    @testset "lines" begin
        text = join(("line $i" for i in 1:1000), '\n')
        reader = XzReader(CursorReader(compress_xz(text)); bufsize = 100)  # lines cross the buffer's end
        @test collect(eachline(reader)) == split(text, '\n')
        reader = XzReader(CursorReader(compress_xz(text)); bufsize = 100)
        @test [readline(reader) for _ in 1:1000] == split(text, '\n')
    end
end

@testset "XzReader" begin
    @test decompress_xz(FOO) == b"foo"
    @test decompress_xz(vcat(FOO, FOO)) == b"foofoo"
    @test decompress_xz(vcat(FOO, zeros(UInt8, 8), FOO)) == b"foofoo"
    reader = XzReader(IOBuffer(compress_xz(SAMPLE)))
    @test BufferIO.fill_buffer(reader) ≤ 256  # a small first read returns early
    @test read(reader) == SAMPLE
    reader = XzReader(IOBuffer(vcat(FOO, FOO)))
    @test read(reader, 4) == b"foof"
    @test position(reader) == 4
    @test read(reader) == b"oo"
    @test eof(reader)
    close(reader)
    @test !isopen(reader)
    @test_throws IOError read(reader, 1)
    @testset "corrupt data" begin
        corrupt = copy(FOO)
        corrupt[[1, 3, 5]] = b"bug"
        err = geterror(() -> decompress_xz(corrupt))
        @test err isa XzError && err.code === :format && occursin("not in the .xz format", sprint(showerror, err))
        reader = XzReader(CursorReader(FOO[1:end-4]))
        @test read(reader, 3) == b"foo"  # decoded before the truncation is found
        err = geterror(() -> read(reader))
        @test err isa XzError && err.code === :truncated
        @test geterror(() -> read(reader)) === err
    end
    err = geterror(() -> decompress_xz(compress_xz(SAMPLE); memlimit = 1))
    @test err isa XzError && err.code === :memlimit
    @test_throws ArgumentError XzReader(IOBuffer(FOO); memlimit = 0)
    @test_throws ArgumentError XzReader(IOBuffer(FOO); bufsize = 0)
    @test_throws ArgumentError XzReader(IOBuffer(FOO); threads = -1)
end

@testset "XzWriter" begin
    Sys.WORD_SIZE == 64 && @test sizeof(XzLib.LZMA.Mt) == 128  # sizeof(lzma_mt)
    data = rand(Xoshiro(2), UInt8, 300_000)
    @testset "threads=$threads, blocksize=$blocksize" for threads in (1, 4), blocksize in (nothing, 50_000)
        compressed = compress_xz(data; threads, blocksize)
        @test decompress_xz(compressed) == data
        @test nblocks(compressed) == if isnothing(blocksize) 1 else cld(length(data), blocksize) end
    end
    @test nblocks(compress_xz(data; blocksize = 0)) == 1
    @testset "input ending on a Block boundary" begin
        compressed = compress_xz(data[1:100_000]; blocksize = 50_000)
        @test decompress_xz(compressed) == data[1:100_000]
        @test nblocks(compressed) == 2
    end
    @testset "single-threaded output is written as input arrives" begin
        sink = VecWriter()
        writer = XzWriter(sink; threads = 1)
        write(writer, rand(UInt8, 4 * 2^20))
        @test length(sink.vec) > 2^20
        close(writer)
    end
    @testset "flush ends a Block, making what is written decodable" for threads in (1, 4)
        sink = VecWriter()
        writer = XzWriter(sink; threads)
        write(writer, "hello")
        flush(writer)
        @test read(XzReader(CursorReader(copy(sink.vec))), 5) == b"hello"
        write(writer, " world")
        close(writer)
        @test decompress_xz(sink.vec) == b"hello world"
        @test nblocks(collect(sink.vec)) == 2
    end
    @testset "closing" begin
        sink = VecWriter()
        writer = XzWriter(sink)
        write(writer, "abc")
        close(writer)
        @test !isopen(writer)
        @test_throws IOError write(writer, "more")
        @test_throws IOError flush(writer)
        close(writer)
        @test decompress_xz(sink.vec) == b"abc"
        io = IOBuffer()
        @test XzWriter(writer -> write(writer, "abc"), io) == 3
        @test !isopen(io)
    end
    @testset "a failing do-block leaves the output unfinished" begin
        sink = VecWriter()
        @test_throws ErrorException XzWriter(sink) do writer
            write(writer, "partial")
            error("interrupted")
        end
        @test geterror(() -> decompress_xz(sink.vec)) isa XzError
    end
    @testset "a failing sink leaves the output unfinished, threads=$threads" for threads in (1, 4)
        out = UInt8[]
        writer = XzWriter(FlakySink(out, 3); threads)
        @test geterror(() -> (write(writer, data); close(writer))) isa ErrorException
        @test !isopen(writer)
        close(writer)
        @test geterror(() -> decompress_xz(out)) isa XzError
    end
    @testset "options" begin
        @testset "automatic threads at level $level" for level in (0, 6, 9)
            options = XzLib.encoderoptions(; level)
            @test 1 ≤ options.threads ≤ XzLib.threadcount(0)
            @test options.threads == 1 || XzLib.LZMA.stream_encoder_mt_memusage(options) ≤ Sys.total_memory() ÷ 4
        end
        @test XzLib.encoderoptions(; threads = 3).threads == 3
        options = XzLib.encoderoptions(; level = 9, threads = XzLib.LZMA.THREADS_MAX)
        @test XzLib.LZMA.stream_encoder_mt_memusage(options) ≤ Sys.total_memory() ÷ 4
        @test XzLib.encoderoptions(; threads = 4, blocksize = 0).threads == 1
        @test XzLib.encoderoptions(; threads = 4, datasize = 1000).threads == 1
        @test XzLib.encoderoptions(; threads = 4, datasize = 100 << 20).threads == 4
        @test compress_xz(data; threads = 4) == compress_xz(data; threads = 1)  # fits in one Block
        @test XzWriter(VecWriter(); threads = 1).blocksize == 24 * 2^20
        @test XzWriter(VecWriter(); threads = 1, level = 0).blocksize == 2^20
        @test XzWriter(VecWriter(); blocksize = 0).blocksize == typemax(Int)
        @test XzWriter(VecWriter(); threads = 4).blocksize == typemax(Int)  # liblzma splits
        @test (XzWriter(VecWriter()).blocksize == typemax(Int)) == (XzLib.threadcount(0) > 1)
        @test_throws ArgumentError XzWriter(VecWriter(); level = 10)
        @test_throws ArgumentError XzWriter(VecWriter(); check = :md5)
        @test_throws ArgumentError XzWriter(VecWriter(); bufsize = 0)
        @test_throws ArgumentError XzWriter(VecWriter(); threads = -1)
        @test_throws ArgumentError compress_xz(UInt8[]; threads = -1)
        @test_throws ArgumentError XzWriter(VecWriter(); threads = -1, blocksize = 0)
        @test_throws ArgumentError XzWriter(VecWriter(); threads = XzLib.LZMA.THREADS_MAX + 1)
        @test_throws ArgumentError XzWriter(VecWriter(); blocksize = -1)
        @test_throws ArgumentError XzWriter(VecWriter(); blocksize = XzLib.LZMA.BLOCK_SIZE_MAX + 1)
    end
end
